+fn table_at<'a>(
+    doc: &'a toml_edit::DocumentMut,
+    spec: &MembershipSpec,
+    authority: AuthorityPath,
+) -> Result<Option<&'a toml_edit::Item>, LocateError> {
+    let mut item = match doc.get(spec.table_path[0]) {
+        Some(item) => item,
+        None => return Ok(None),
+    };
+    for (index, key) in spec.table_path.iter().enumerate().skip(1) {
+        item = item.get(*key).ok_or_else(|| {
+            authority.field_error(
+                spec.table_path[..=index].join(".").leak(),
+                "must be a table containing the workspace authority",
+            )
+        })?;
+    }
+    if item.as_table().is_none() {
+        return Err(authority.field_error(
+            spec.table_path.join(".").leak(),
+            "must be a workspace table",
+        ));
+    }
+    Ok(Some(item))
