    MembershipRead {
        ecosystem: &'static str,
        path: PathBuf,
        message: String,
    },

    #[error("cannot parse {ecosystem} workspace authority `{}` as {parser}: {message}", .path.display())]
    #[diagnostic(
        code(E035),
        help("Fix the authority file syntax and retry discovery; Callisto did not scan without it.")
    )]
    MembershipParse {
        ecosystem: &'static str,
        path: PathBuf,
        parser: &'static str,
        message: String,
    },

    #[error("{ecosystem} workspace authority `{}` has invalid `{field}`: {detail}", .path.display())]
    #[diagnostic(
        code(E036),
        help("Use the documented workspace field shape and retry discovery; Callisto did not scan without it.")
    )]
    MembershipField {
        ecosystem: &'static str,
        path: PathBuf,
        field: &'static str,
        detail: &'static str,
    },

    #[error("{ecosystem} workspace authority `{}` has invalid `{field}` glob `{pattern}`: {message}", .path.display())]
    #[diagnostic(
        code(E037),
        help("Correct or remove the invalid workspace glob and retry discovery; Callisto did not scan without it.")
    )]
    MembershipGlob {
        ecosystem: &'static str,
        path: PathBuf,
        field: &'static str,
        pattern: String,
        message: String,
    },

    /// A VCS operation failed during workspace location. This variant exists
    /// so that callers who need to distinguish filesystem-structure errors
    /// (WorkspaceRootNotFound, Walk) from VCS errors (e.g., a git repository
    /// that could not be opened or queried during locate) can do so.
    #[error("VCS error during workspace location: {0}")]
